import { getValueByAccessor } from './get-value-by-accessor.js';
import type { MinMax } from '../../core/types/min-max.js';
import type { XYChartData, XYChartVariants } from '../types/xy-chart.js';

export const getMinMax = (
  seriesVariantProps: XYChartVariants[],
  data: XYChartData[],
) => {
  const minMaxX: MinMax = {
    min: Infinity,
    max: -Infinity,
  };
  const minMaxY: MinMax = {
    min: Infinity,
    max: -Infinity,
  };

  const minMaxValue: MinMax = {
    min: Infinity,
    max: -Infinity,
  };

  const heatmapProps = seriesVariantProps[0];

  for (let i = 0; i < heatmapProps.length; i++) {
    const seriesProps = heatmapProps[i];
    const seriesData = seriesProps.data ? seriesProps.data : data;

    for (let j = 0; j < seriesData.length; j++) {
      const item = seriesData[j];

      const x0 = getValueByAccessor(item, seriesProps.x0Accessor);
      const x1 = getValueByAccessor(item, seriesProps.x1Accessor);
      const y0 = getValueByAccessor(item, seriesProps.y0Accessor);
      const y1 = getValueByAccessor(item, seriesProps.y1Accessor);
      const value = getValueByAccessor(item, seriesProps.valueAccessor);

      minMaxX.min = Math.min(
        minMaxX.min,
        x0 === undefined ? minMaxX.min : x0,
        x1 === undefined ? minMaxX.min : x1,
      );
      minMaxX.max = Math.max(
        minMaxX.max,
        x0 === undefined ? minMaxX.max : x0,
        x1 === undefined ? minMaxX.max : x1,
      );

      minMaxY.min = Math.min(
        minMaxY.min,
        y0 === undefined ? minMaxY.min : y0,
        y1 === undefined ? minMaxY.min : y1,
      );
      minMaxY.max = Math.max(
        minMaxY.max,
        y0 === undefined ? minMaxY.max : y0,
        y1 === undefined ? minMaxY.max : y1,
      );

      minMaxValue.min = Math.min(
        minMaxValue.min,
        value === undefined ? minMaxValue.min : value,
      );
      minMaxValue.max = Math.max(
        minMaxValue.max,
        value === undefined ? minMaxValue.max : value,
      );
    }
  }

  return { minMaxX, minMaxY, minMaxValue };
};
